def main():
    if not os.path.exists(STATE_PATH):
        print(f"ERROR: {STATE_PATH} not found", file=sys.stderr)
        sys.exit(1)

    with open(STATE_PATH, "r", encoding="utf-8") as f:
        state = json.load(f)

    # Archive current last_decision to front of history
    current_last = state.get("last_decision", {})
    if current_last:
        archived = dict(current_last)
        archived["archived_from"] = "last_decision"
        archived["archived_at"] = "2026-08-31 10:45:00"
        history = state.get("history", [])
        history.insert(0, archived)
        state["history"] = history
        print(
            f"Archived last_decision ({current_last.get('ist_time','?')}) "
            f"to history (now {len(history)} entries)"
        )

    # Replace last_decision
    state["last_decision"] = NEW_DECISION
    print(f"Set new last_decision: {NEW_DECISION['ist_time']} bias={NEW_DECISION['bias']}")

    # Bump call_count_today
    old_count = state.get("call_count_today", 0)
    state["call_count_today"] = old_count + 1
    print(f"Bumped call_count_today: {old_count} -> {old_count + 1}")

    # Update top-level timestamp and last_updated_ist
    state["timestamp"] = "2026-08-31T05:15:00Z"
    state["last_updated_ist"] = "2026-08-31 10:45:00"

    # Atomic write (tmp + replace)
    tmp_path = STATE_PATH + ".tmp"
    with open(tmp_path, "w", encoding="utf-8") as f:
        json.dump(state, f, indent=2, ensure_ascii=False)
    os.replace(tmp_path, STATE_PATH)
    print(f"Wrote {STATE_PATH} atomically")


if __name__ == "__main__":
    main()
